function mstWeight(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i)
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]
      x = parent[x]
    }
    return x
  }
  const sorted = [...edges].sort((a, b) => a[2] - b[2])
  let total = 0
  let used = 0
  for (const [u, v, w] of sorted) {
    const a = find(u)
    const b = find(v)
    if (a !== b) {
      parent[b] = a
      total += w
      used++
    }
  }
  return used === n - 1 ? total : -1
}

