function eulerCircuit(edges) {
  if (edges.length === 0) return []
  const adj = new Map()
  const bal = new Map()
  for (const [a, b] of edges) {
    if (!adj.has(a)) adj.set(a, [])
    adj.get(a).push(b)
    bal.set(a, (bal.get(a) || 0) + 1)
    bal.set(b, (bal.get(b) || 0) - 1)
  }
  for (const v of bal.values()) if (v !== 0) return []
  const next = new Map()
  const start = edges[0][0]
  const stack = [start]
  const path = []
  while (stack.length) {
    const u = stack[stack.length - 1]
    const list = adj.get(u) || []
    const i = next.get(u) || 0
    if (i < list.length) {
      next.set(u, i + 1)
      stack.push(list[i])
    } else {
      path.push(stack.pop())
    }
  }
  path.reverse()
  return path.length === edges.length + 1 ? path : []
}
